import java.util.Arrays;
public class TerrainDetailTest{
 public static void main(String[]args){var g=new TerrainGraph();var node=g.add(TerrainGraph.Type.TERRAIN_DETAIL,0,0);int n=128;var base=new EnvironmentMap(EnvironmentMap.filled(n*n,100));var full=TerrainDetail.apply(node,base,n,n,62,2024,0,0,()->false);var repeat=TerrainDetail.apply(node,base,n,n,62,2024,0,0,()->false);if(!Arrays.equals(full.height,repeat.height))throw new AssertionError("Not deterministic");float low=999,high=-999;for(float h:full.height){low=Math.min(low,h);high=Math.max(high,h);if(Math.abs(h-100)>3.001)throw new AssertionError("Too strong");}if(high-low<2)throw new AssertionError("Missing detail");for(int tz=0;tz<2;tz++)for(int tx=0;tx<2;tx++){var tile=TerrainDetail.apply(node,new EnvironmentMap(EnvironmentMap.filled(64*64,100)),64,64,62,2024,tx*64,tz*64,()->false);for(int z=0;z<64;z++)for(int x=0;x<64;x++)if(tile.height[z*64+x]!=full.height[(tz*64+z)*128+tx*64+x])throw new AssertionError("Region seam");}for(float h:new float[]{40,62,63,512}){var b=new EnvironmentMap(EnvironmentMap.filled(16,h));if(!Arrays.equals(b.height,TerrainDetail.apply(node,b,4,4,62,2024,0,0,()->false).height))throw new AssertionError("Water or peak changed");}node.values.put("amount",0.0);if(!Arrays.equals(base.height,TerrainDetail.apply(node,base,n,n,62,2024,0,0,()->false).height))throw new AssertionError("Zero strength");System.out.println("PASS: bounded small detail, deterministic continuous regions, preserved shores/water/peak and zero strength");}
}
